// The published 2.0.0-rc.21 signatures reduced to the forms used here (`dist/types/signals.d.ts` `createMemo`, `createEffect` with
// `MemoOptions`/`EffectOptions` cut to `sync`; `dist/types/core/owner.d.ts` `onCleanup`).
export function createMemo<T>(compute: (prev: T | undefined) => T, options?: { sync?: boolean }): () => T;
export function createEffect<T>(
  compute: (prev: T | undefined) => T,
  effect: (value: T, prev?: T) => (() => void) | void,
  options?: { sync?: boolean },
): void;
export function onCleanup(fn: () => void): () => void;
